CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE "people" ("id" UUID PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "full_name" TEXT NOT NULL, "tax_id" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "notes" ("id" UUID PRIMARY KEY, "person_id" UUID NOT NULL REFERENCES "people"("id"), "body" TEXT NOT NULL);
CREATE TABLE "note_embeddings" ("source_pk" UUID PRIMARY KEY REFERENCES "notes"("id") ON DELETE CASCADE, "vector" vector(3) NOT NULL);
CREATE TABLE "sessions" ("id" TEXT PRIMARY KEY, "token" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
